import { Injectable } from '@angular/core';
import { BehaviorSubject, Observable } from 'rxjs';
import { BrowserNotificationService } from './browser-notification.service';
import { RealtimeGatewayService, RealtimeMessage, RealtimeRoomRef } from './realtime-gateway.service';

/**
 * ユーザーが作成したチャットルームやミニチャットでのメッセージを
 * ChatPageComponent と AppComponent (Messenger 風レール + ミニウィンドウ) で
 * 共有するためのサービス。
 *
 * - localStorage に保存し、ページ遷移・リロードを跨いでも残す
 * - 依存を増やさないため、最小限のデータ型のみを扱う
 */

export interface SharedRoom {
  id: string;
  name: string;
  initial: string;
  avatarColor: string;
  avatarImage?: string;
  type: 'direct' | 'group' | 'my';
  unreadCount?: number;
  online?: boolean;
  lastMessage?: string;
  timestamp?: string;
  /** 最終更新 unix ms (一覧 recency ソート用) */
  updatedAt?: number;
  /** グループのメンバーアバター (重なり表示用、最大 3 名分) */
  memberAvatars?: Array<{ initial: string; color: string; image?: string }>;
  /** chat-page 固有のフィールドもまとめて保持 (メンバー等) */
  raw?: any;
}

export interface MiniMessage {
  id: string;
  roomId: string;
  text: string;
  time: string;
  isMe: boolean;
  senderName?: string;
  /* 修正 No.47 (2026-04-24): 拡張フィールド – reply/添付/タグ保持 */
  replyTo?: string;
  attachments?: any[];
  tags?: string[];
  dateLabel?: string;
}

const ROOMS_KEY = 'schecon.userRooms.v1';
const MESSAGES_KEY_PREFIX = 'schecon.miniMessages.v1.';

@Injectable({ providedIn: 'root' })
export class ChatStateService {
  private userRooms$ = new BehaviorSubject<SharedRoom[]>(this.loadRooms());
  private messagesByRoom$ = new BehaviorSubject<Record<string, MiniMessage[]>>(this.loadAllMessages());

  constructor(
    private browserNotify: BrowserNotificationService,
    private gateway: RealtimeGatewayService,
  ) {
    // 他タブからの受信イベントを自タブの状態へ反映
    this.wireRealtimeSubscriptions();
  }

  /**
   * RealtimeGateway からのイベントを受けて、自タブの状態を更新する。
   * 自タブの publish は clientMsgId により既に除外されているため、
   * ここに到達するイベントは全て "他タブ発" と扱える。
   */
  private wireRealtimeSubscriptions(): void {
    // 他タブで送信されたメッセージ
    this.gateway.on('message.created').subscribe(({ roomId, message }) => {
      const map = { ...this.messagesByRoom$.value };
      const list = map[roomId] || [];
      if (list.some(m => m.id === message.id)) return; // 重複排除
      map[roomId] = [...list, {
        id: message.id,
        roomId,
        text: message.text,
        time: message.time,
        isMe: message.isMe,
        senderName: message.senderName,
      }];
      this.messagesByRoom$.next(map);
      this.saveMessagesForRoom(roomId, map[roomId]);

      // 相手からの受信なら unread++ と ルーム lastMessage 更新 & 通知
      if (!message.isMe) {
        const existing = this.userRooms$.value.find(r => r.id === roomId);
        const currentUnread = existing?.unreadCount || 0;
        this.updateUserRoom(roomId, {
          lastMessage: message.text.slice(0, 60),
          timestamp: message.time,
          updatedAt: Date.now(),
          unreadCount: currentUnread + 1,
        });
        this.browserNotify.enqueue({
          roomId,
          senderName: message.senderName || '相手',
          preview: message.text,
          timestamp: Date.now(),
          roomName: existing?.name,
          senderAvatar: existing?.avatarImage,
        });
      } else {
        // 自送信の別タブからのブロードキャスト: 一覧を最新化
        this.updateUserRoom(roomId, {
          lastMessage: message.text.slice(0, 60),
          timestamp: message.time,
          updatedAt: Date.now(),
        });
      }
    });

    // 他タブで新規作成されたルーム
    this.gateway.on('thread.created').subscribe(({ room }) => {
      if (this.userRooms$.value.some(r => r.id === room.id)) return;
      const next: SharedRoom[] = [{
        id: room.id,
        name: room.name,
        initial: room.initial,
        avatarColor: room.avatarColor,
        avatarImage: room.avatarImage,
        type: room.type,
        lastMessage: room.lastMessage,
        timestamp: room.timestamp,
        updatedAt: room.updatedAt || Date.now(),
        unreadCount: room.unreadCount || 0,
      }, ...this.userRooms$.value];
      this.userRooms$.next(next);
      this.saveRooms(next);
    });

    // 他タブからの部分更新
    this.gateway.on('thread.updated').subscribe(({ roomId, patch }) => {
      const cur = this.userRooms$.value;
      if (!cur.some(r => r.id === roomId)) return;
      const next = cur.map(r => r.id === roomId ? { ...r, ...(patch as Partial<SharedRoom>) } : r);
      this.userRooms$.next(next);
      this.saveRooms(next);
    });

    // 未読数の他タブ同期 (既読化 / バッジ)
    this.gateway.on('unread.updated').subscribe(({ roomId, unreadCount }) => {
      const cur = this.userRooms$.value;
      if (!cur.some(r => r.id === roomId)) return;
      const next = cur.map(r => r.id === roomId ? { ...r, unreadCount } : r);
      this.userRooms$.next(next);
      this.saveRooms(next);
    });
  }

  getGateway(): RealtimeGatewayService { return this.gateway; }

  /** 追加されたルーム (Observable) */
  getUserRooms(): Observable<SharedRoom[]> {
    return this.userRooms$.asObservable();
  }

  snapshotUserRooms(): SharedRoom[] {
    return this.userRooms$.value;
  }

  addUserRoom(room: SharedRoom): void {
    const cur = this.userRooms$.value;
    // 重複チェック (同一 ID があれば無視)
    if (cur.some(r => r.id === room.id)) return;
    const next = [room, ...cur];
    this.userRooms$.next(next);
    this.saveRooms(next);
    // 他タブへブロードキャスト
    this.gateway.publish({
      type: 'thread.created',
      room: {
        id: room.id,
        name: room.name,
        initial: room.initial,
        avatarColor: room.avatarColor,
        avatarImage: room.avatarImage,
        type: room.type,
        lastMessage: room.lastMessage,
        timestamp: room.timestamp,
        updatedAt: room.updatedAt,
        unreadCount: room.unreadCount,
      },
    });
  }

  updateUserRoom(roomId: string, patch: Partial<SharedRoom>): void {
    const next = this.userRooms$.value.map(r => r.id === roomId ? { ...r, ...patch } : r);
    this.userRooms$.next(next);
    this.saveRooms(next);
    // 他タブへブロードキャスト (循環を避けるため raw は送らず基本フィールドのみ)
    const rtPatch: Partial<RealtimeRoomRef> = {};
    if (patch.name !== undefined) rtPatch.name = patch.name;
    if (patch.lastMessage !== undefined) rtPatch.lastMessage = patch.lastMessage;
    if (patch.timestamp !== undefined) rtPatch.timestamp = patch.timestamp;
    if (patch.updatedAt !== undefined) rtPatch.updatedAt = patch.updatedAt;
    if (patch.unreadCount !== undefined) rtPatch.unreadCount = patch.unreadCount;
    if (patch.avatarColor !== undefined) rtPatch.avatarColor = patch.avatarColor;
    if (patch.avatarImage !== undefined) rtPatch.avatarImage = patch.avatarImage;
    if (Object.keys(rtPatch).length > 0) {
      this.gateway.publish({ type: 'thread.updated', roomId, patch: rtPatch });
    }
  }

  /** 特定のルームのメッセージ */
  getMessages(roomId: string): MiniMessage[] {
    return this.messagesByRoom$.value[roomId] || [];
  }

  getAllMessages$(): Observable<Record<string, MiniMessage[]>> {
    return this.messagesByRoom$.asObservable();
  }

  /* 修正 No.53 (2026-04-24): 永続化されたメッセージをシードチャットへ復元するために
     全ルームのメッセージスナップショットを返す。
     ChatPageComponent の ngOnInit で this.messages にマージして
     リロード / ルーム遷移後も投稿が消えない状態にする。 */
  getAllMessagesSnapshot(): Record<string, MiniMessage[]> {
    return this.messagesByRoom$.value;
  }

  sendMessage(roomId: string, text: string, senderName?: string): MiniMessage {
    const trimmed = text.trim();
    if (!trimmed) {
      return { id: '', roomId, text: '', time: '', isMe: true };
    }
    const now = new Date();
    const hh = String(now.getHours()).padStart(2, '0');
    const mm = String(now.getMinutes()).padStart(2, '0');
    const msg: MiniMessage = {
      id: 'mini-' + Date.now() + '-' + Math.random().toString(36).slice(2, 6),
      roomId,
      text: trimmed,
      time: `${hh}:${mm}`,
      isMe: true,
      senderName: senderName || '石澤（自分）',
    };
    const map = { ...this.messagesByRoom$.value };
    map[roomId] = [...(map[roomId] || []), msg];
    this.messagesByRoom$.next(map);
    this.saveMessagesForRoom(roomId, map[roomId]);
    // 送信時にこのルームの lastMessage / updatedAt を更新 (自分送信なので unread は触らない)
    // updateUserRoom 内で thread.updated もブロードキャスト
    this.updateUserRoom(roomId, {
      lastMessage: trimmed.slice(0, 60),
      timestamp: `${hh}:${mm}`,
      updatedAt: Date.now(),
    });
    // 他タブへメッセージ本体もブロードキャスト
    this.gateway.publish({
      type: 'message.created',
      roomId,
      message: {
        id: msg.id,
        roomId,
        text: msg.text,
        time: msg.time,
        isMe: true,
        senderName: msg.senderName,
      },
    });
    return msg;
  }

  /** 相手 (AI もしくはシミュレート) からの受信メッセージ */
  receiveMessage(roomId: string, text: string, senderName = '相手'): MiniMessage {
    const trimmed = text.trim();
    if (!trimmed) {
      return { id: '', roomId, text: '', time: '', isMe: false };
    }
    const now = new Date();
    const hh = String(now.getHours()).padStart(2, '0');
    const mm = String(now.getMinutes()).padStart(2, '0');
    const msg: MiniMessage = {
      id: 'mini-recv-' + Date.now() + '-' + Math.random().toString(36).slice(2, 6),
      roomId,
      text: trimmed,
      time: `${hh}:${mm}`,
      isMe: false,
      senderName,
    };
    const map = { ...this.messagesByRoom$.value };
    map[roomId] = [...(map[roomId] || []), msg];
    this.messagesByRoom$.next(map);
    this.saveMessagesForRoom(roomId, map[roomId]);
    // 受信 → 未読 +1 + lastMessage / updatedAt 更新 (updateUserRoom 内で thread.updated ブロードキャスト)
    const existing = this.userRooms$.value.find(r => r.id === roomId);
    const currentUnread = existing?.unreadCount || 0;
    this.updateUserRoom(roomId, {
      lastMessage: trimmed.slice(0, 60),
      timestamp: `${hh}:${mm}`,
      updatedAt: Date.now(),
      unreadCount: currentUnread + 1,
    });
    // ブラウザ通知 (BrowserNotificationService に完全委譲)
    this.browserNotify.enqueue({
      roomId,
      senderName,
      preview: trimmed,
      timestamp: Date.now(),
      roomName: existing?.name,
      senderAvatar: existing?.avatarImage,
    });
    // 他タブへ message.created ブロードキャスト
    this.gateway.publish({
      type: 'message.created',
      roomId,
      message: {
        id: msg.id,
        roomId,
        text: msg.text,
        time: msg.time,
        isMe: false,
        senderName,
      },
    });
    return msg;
  }

  /** 互換: 旧コードで injectAutoReply 呼び出しがあるため receiveMessage の別名として残す */
  injectAutoReply(roomId: string, text: string, senderName = 'スケコンAI'): void {
    this.receiveMessage(roomId, text, senderName);
  }

  /**
   * 既存 ID を保ったままメッセージを登録 (全画面チャットで送信した際、
   * chat-page.messages と ChatStateService を完全に同じ ID で揃える用)。
   * 他タブへも message.created でブロードキャストする。
   */
  registerExternalMessage(msg: MiniMessage): void {
    const map = { ...this.messagesByRoom$.value };
    const list = map[msg.roomId] || [];
    if (list.some(m => m.id === msg.id)) return;
    map[msg.roomId] = [...list, msg];
    this.messagesByRoom$.next(map);
    this.saveMessagesForRoom(msg.roomId, map[msg.roomId]);
    this.gateway.publish({
      type: 'message.created',
      roomId: msg.roomId,
      message: {
        id: msg.id,
        roomId: msg.roomId,
        text: msg.text,
        time: msg.time,
        isMe: msg.isMe,
        senderName: msg.senderName,
      },
    });
  }

  /** ルームを既読にする (unreadCount = 0)。他タブへも unread.updated を飛ばす */
  markRoomAsRead(roomId: string): void {
    const existing = this.userRooms$.value.find(r => r.id === roomId);
    if (!existing || !existing.unreadCount) return;
    this.updateUserRoom(roomId, { unreadCount: 0 });
    // 明示的な unread.updated も発行 (updateUserRoom の thread.updated とは別軸で監視しやすく)
    this.gateway.publish({ type: 'unread.updated', roomId, unreadCount: 0 });
    this.gateway.publish({ type: 'message.read', roomId, at: Date.now() });
  }

  /** 全ルームの未読合計 */
  totalUnread(): number {
    return this.userRooms$.value.reduce((s, r) => s + (r.unreadCount || 0), 0);
  }

  // 通知ロジックは BrowserNotificationService に分離済み
  // (権限取得 / クールダウン / サマリ化 / アクティブルーム判定 / レート制限 / denied 再設定ガイド)

  // ====== localStorage helpers ======
  private loadRooms(): SharedRoom[] {
    if (typeof window === 'undefined' || !window.localStorage) return [];
    try {
      const raw = window.localStorage.getItem(ROOMS_KEY);
      if (!raw) return [];
      const arr = JSON.parse(raw);
      return Array.isArray(arr) ? arr : [];
    } catch {
      return [];
    }
  }

  private saveRooms(rooms: SharedRoom[]): void {
    if (typeof window === 'undefined' || !window.localStorage) return;
    try {
      window.localStorage.setItem(ROOMS_KEY, JSON.stringify(rooms));
    } catch {
      /* quota/serialize error ignored */
    }
  }

  private loadAllMessages(): Record<string, MiniMessage[]> {
    if (typeof window === 'undefined' || !window.localStorage) return {};
    const result: Record<string, MiniMessage[]> = {};
    try {
      for (let i = 0; i < window.localStorage.length; i++) {
        const key = window.localStorage.key(i);
        if (!key || !key.startsWith(MESSAGES_KEY_PREFIX)) continue;
        const roomId = key.substring(MESSAGES_KEY_PREFIX.length);
        const raw = window.localStorage.getItem(key);
        if (!raw) continue;
        try {
          const msgs = JSON.parse(raw);
          if (Array.isArray(msgs)) result[roomId] = msgs;
        } catch { /* skip */ }
      }
    } catch { /* skip */ }
    return result;
  }

  private saveMessagesForRoom(roomId: string, msgs: MiniMessage[]): void {
    if (typeof window === 'undefined' || !window.localStorage) return;
    try {
      window.localStorage.setItem(MESSAGES_KEY_PREFIX + roomId, JSON.stringify(msgs));
    } catch { /* skip */ }
  }
}
