import { Injectable, NgZone } from '@angular/core';
import { BehaviorSubject, Observable } from 'rxjs';

/**
 * BrowserNotificationService
 *
 * ブラウザ通知 (Notification API) の送出責務をここ 1 か所に集約する。
 *
 * 設計原則 (Slack 風):
 * 1. ページ読み込み直後に権限要求しない — エンゲージメント後に要求
 * 2. メッセージ 1 件ごとに通知しない — クールダウン + サマリ化
 * 3. 画面が見えている時は通知しない (document.visibilityState === 'visible')
 * 4. ユーザーが「受信したルームを既に開いている」時も通知しない
 * 5. 通知クリックで該当ルームへディープリンク
 * 6. 拒否状態は回復不可能 — Chrome/Edge のサイト設定への誘導
 *
 * 将来拡張 (Push API / Service Worker) に備え、イベントは Observable で公開する。
 */

export type PermissionState = 'granted' | 'denied' | 'default' | 'unsupported';

export interface NotificationPayload {
  /** どのルーム宛の通知か */
  roomId: string;
  /** 送信者名 (グループの場合は送信者、DM の場合は相手名) */
  senderName: string;
  /** 本文プレビュー (60 字程度推奨) */
  preview: string;
  /** このメッセージの発生時刻 unix ms */
  timestamp?: number;
  /** ルーム名 (グループ通知の本文作成用) */
  roomName?: string;
  /** 送信者アバター URL (iOS/Android ではアイコンとして表示) */
  senderAvatar?: string;
}

/**
 * 権限要求のトリガ理由 (分析・デバッグ用)
 */
export type PermissionRequestReason =
  | 'user-settings'       // 設定画面から明示的に ON
  | 'banner-cta'          // 画面下のバナーの「オンにする」ボタン
  | 'first-message-sent'  // 初回メッセージ送信後の推奨
  | 'unread-missed';      // 新着を受信したが画面非アクティブで未読化

const STORAGE_KEYS = {
  /** 権限要求プロンプトを表示した最後の時刻 (回数制限) */
  LAST_PROMPT_TIME: 'schecon.notify.lastPrompt.v1',
  /** ユーザーが「あとで」を押した回数 */
  DISMISS_COUNT: 'schecon.notify.dismissCount.v1',
  /** ユーザーが「もう出さない」を押したか */
  SUPPRESSED: 'schecon.notify.suppressed.v1',
  /** ルーム別: 最後に通知した時刻 (クールダウン用) */
  ROOM_LAST_NOTIFY: 'schecon.notify.roomLast.v1',
  /** グローバル: アプリ内の通知 ON/OFF (権限は granted でもユーザーがアプリ側で OFF にできる) */
  APP_ENABLED: 'schecon.notify.appEnabled.v1',
};

// ====== アグリゲーション設定 ======
const AGGREGATION_WINDOW_MS = 3000;      // 3 秒以内の連続受信はまとめる
const ROOM_COOLDOWN_MS = 30 * 1000;      // 同一ルームは 30 秒に 1 回まで
const MAX_NOTIFY_PER_MINUTE = 3;         // 全体で 1 分間に最大 3 通 (Slack 風)
const DISMISS_SNOOZE_STEPS_MS = [
  60 * 60 * 1000,       // 1 時間 (初回あとで)
  4 * 60 * 60 * 1000,   // 4 時間 (2 回目)
  24 * 60 * 60 * 1000,  // 24 時間 (3 回目以降)
];

@Injectable({ providedIn: 'root' })
export class BrowserNotificationService {
  // ====== 内部状態 ======
  private pendingByRoom = new Map<string, NotificationPayload[]>();
  private flushTimer: any = null;
  private recentNotifyTimes: number[] = []; // rate limit 用のリングバッファ

  // ====== 外部公開: Observable ======
  private permission$ = new BehaviorSubject<PermissionState>(this.readPermission());
  private appEnabled$ = new BehaviorSubject<boolean>(this.readAppEnabled());

  /** 現在ユーザーが "どのルームを開いているか"。同じルームは通知不要 */
  private activeRoomId: string | null = null;

  constructor(private ngZone: NgZone) {
    if (typeof document !== 'undefined') {
      // 画面が visible になったタイミングで permission を再チェック (他タブで変更された可能性)
      document.addEventListener('visibilitychange', () => {
        if (document.visibilityState === 'visible') {
          this.refreshPermission();
        }
      });
    }
    // Permissions API があれば notification 権限の onchange を購読 (ユーザー指示 2026-04-21)
    // → ブラウザ設定側で "許可" に変更された瞬間を UI に反映
    this.subscribeToPermissionsApi();
  }

  private subscribeToPermissionsApi(): void {
    try {
      const anyNav = typeof navigator !== 'undefined' ? (navigator as any) : null;
      if (!anyNav || !anyNav.permissions || !anyNav.permissions.query) return;
      anyNav.permissions
        .query({ name: 'notifications' })
        .then((status: any) => {
          // 初期反映
          this.ngZone.run(() => this.permission$.next(status.state as PermissionState));
          status.onchange = () => {
            this.ngZone.run(() => this.permission$.next(status.state as PermissionState));
          };
        })
        .catch(() => {
          /* ignored: Safari 等で非対応 */
        });
    } catch {
      /* ignore */
    }
  }

  // ==================================================================
  // 権限状態
  // ==================================================================
  getPermission(): PermissionState {
    return this.readPermission();
  }

  getPermission$(): Observable<PermissionState> {
    return this.permission$.asObservable();
  }

  private readPermission(): PermissionState {
    if (typeof window === 'undefined' || !('Notification' in window)) return 'unsupported';
    return Notification.permission as PermissionState;
  }

  private refreshPermission(): void {
    const cur = this.readPermission();
    if (cur !== this.permission$.value) {
      this.ngZone.run(() => this.permission$.next(cur));
    }
  }

  // ==================================================================
  // アプリ内 ON/OFF (権限とは別軸)
  // ==================================================================
  isAppEnabled(): boolean {
    return this.appEnabled$.value;
  }

  getAppEnabled$(): Observable<boolean> {
    return this.appEnabled$.asObservable();
  }

  setAppEnabled(enabled: boolean): void {
    this.writeAppEnabled(enabled);
    this.appEnabled$.next(enabled);
  }

  private readAppEnabled(): boolean {
    if (typeof window === 'undefined' || !window.localStorage) return true;
    const v = window.localStorage.getItem(STORAGE_KEYS.APP_ENABLED);
    if (v === null) return true; // デフォルト ON
    return v === '1';
  }

  private writeAppEnabled(enabled: boolean): void {
    if (typeof window === 'undefined' || !window.localStorage) return;
    try { window.localStorage.setItem(STORAGE_KEYS.APP_ENABLED, enabled ? '1' : '0'); } catch {}
  }

  // ==================================================================
  // 権限要求: Slack 風にエンゲージメント後にリクエスト
  // ==================================================================
  /**
   * バナーを今表示すべきかの判定
   * - 権限が default
   * - suppressed (もう出さない) ではない
   * - 前回の dismiss から snooze 期間経過
   */
  shouldShowBanner(): boolean {
    const p = this.getPermission();
    if (p !== 'default') return false;
    if (typeof window === 'undefined' || !window.localStorage) return true;
    try {
      if (window.localStorage.getItem(STORAGE_KEYS.SUPPRESSED) === '1') return false;
      const last = Number(window.localStorage.getItem(STORAGE_KEYS.LAST_PROMPT_TIME) || '0');
      const dismissCount = Number(window.localStorage.getItem(STORAGE_KEYS.DISMISS_COUNT) || '0');
      if (!last) return true; // まだ一度も見せていない
      const snoozeMs = DISMISS_SNOOZE_STEPS_MS[Math.min(dismissCount, DISMISS_SNOOZE_STEPS_MS.length - 1)];
      return (Date.now() - last) > snoozeMs;
    } catch {
      return true;
    }
  }

  /** バナー表示を記録 (次回 snooze 計算用) */
  markBannerShown(): void {
    if (typeof window === 'undefined' || !window.localStorage) return;
    try {
      window.localStorage.setItem(STORAGE_KEYS.LAST_PROMPT_TIME, String(Date.now()));
    } catch {}
  }

  /** あとで: snooze を進める */
  dismissBanner(): void {
    if (typeof window === 'undefined' || !window.localStorage) return;
    try {
      const cur = Number(window.localStorage.getItem(STORAGE_KEYS.DISMISS_COUNT) || '0');
      window.localStorage.setItem(STORAGE_KEYS.DISMISS_COUNT, String(cur + 1));
      window.localStorage.setItem(STORAGE_KEYS.LAST_PROMPT_TIME, String(Date.now()));
    } catch {}
  }

  /** もう出さない: 恒久停止 */
  suppressBannerForever(): void {
    if (typeof window === 'undefined' || !window.localStorage) return;
    try { window.localStorage.setItem(STORAGE_KEYS.SUPPRESSED, '1'); } catch {}
  }

  /**
   * 権限を要求。reason は分析・デバッグ用。
   * 注意: Chrome/Edge ではページ読込直後の要求を禁じている実装があるため、
   * 必ずユーザーアクション (クリック等) 内で呼ぶこと。
   *
   * 既に denied の場合でもブラウザによっては再プロンプトできる可能性があるため、
   * 呼び出しは試行する。成功しない場合は呼び出し側で手動解除フローへ誘導する。
   */
  async requestPermission(_reason: PermissionRequestReason): Promise<PermissionState> {
    if (typeof window === 'undefined' || !('Notification' in window)) return 'unsupported';
    try {
      const p = await Notification.requestPermission();
      this.markBannerShown();
      this.permission$.next(p as PermissionState);
      return p as PermissionState;
    } catch {
      return 'denied';
    }
  }

  /**
   * ブラウザ設定で手動解除できたかを確認するための再チェック (ユーザー指示 2026-04-21)
   * denied モーダルから呼ばれる。許可された場合は permission$ を更新してテスト通知を送る。
   */
  async recheckPermission(): Promise<PermissionState> {
    const cur = this.readPermission();
    if (cur !== this.permission$.value) {
      this.permission$.next(cur);
    }
    return cur;
  }

  /**
   * テスト通知を送出 (ユーザー指示 2026-04-21): 「正しいボタン」で
   * 通知が本当に届くかをその場で確認できる。
   */
  sendTestNotification(): boolean {
    if (this.getPermission() !== 'granted') return false;
    try {
      const n = new Notification('スケコン: 通知テスト', {
        body: '通知は正しく届きます。チャットの新着メッセージなどで使用されます。',
        icon: '/schecon-demo/assets/imgs/common/schecon-favicon.png',
        tag: 'schecon-test',
      });
      n.onclick = () => {
        try { window.focus(); } finally { n.close(); }
      };
      this.playNotificationChime();
      return true;
    } catch {
      return false;
    }
  }

  // ==================================================================
  // 通知送出 (核心)
  // ==================================================================
  /**
   * 受信メッセージをキューに入れる。
   * - 画面が visible かつ activeRoom が一致 → 通知しない (Slack 風)
   * - 権限 ≠ granted → 通知しない
   * - ルームごとのクールダウン内 → 集約のみ
   * - レート制限を超える → 集約のみ
   * - 上記全てクリアで 3 秒後にサマリ送出
   */
  enqueue(payload: NotificationPayload): void {
    if (this.getPermission() !== 'granted') return;
    if (!this.isAppEnabled()) return;
    if (!this.shouldDeliver(payload)) return;

    // 同一ルームに未通知で重複する内容があれば、古いのを捨てる (最新だけ残す)
    const list = this.pendingByRoom.get(payload.roomId) || [];
    list.push(payload);
    this.pendingByRoom.set(payload.roomId, list);

    this.scheduleFlush();
  }

  /** 現在ユーザーが開いているルームを通知サービスへ伝える (重複通知回避) */
  setActiveRoom(roomId: string | null): void {
    this.activeRoomId = roomId;
  }

  /**
   * 画面が visible かつ対象ルームを開いているときは通知しない (Slack 風)
   */
  private shouldDeliver(p: NotificationPayload): boolean {
    if (typeof document !== 'undefined' && document.visibilityState === 'visible') {
      if (this.activeRoomId && this.activeRoomId === p.roomId) return false;
    }
    return true;
  }

  private scheduleFlush(): void {
    if (this.flushTimer) return; // 既存のタイマーが走っているならまとめる
    this.flushTimer = setTimeout(() => {
      this.flushTimer = null;
      this.flush();
    }, AGGREGATION_WINDOW_MS);
  }

  private flush(): void {
    // アクティブな制限をチェック
    const now = Date.now();
    this.recentNotifyTimes = this.recentNotifyTimes.filter(t => now - t < 60_000);
    if (this.recentNotifyTimes.length >= MAX_NOTIFY_PER_MINUTE) {
      // レート超過: サマリ 1 通だけにまとめる
      this.fireSummary();
      this.pendingByRoom.clear();
      return;
    }

    const rooms = Array.from(this.pendingByRoom.entries());
    if (!rooms.length) return;

    const totalMsgs = rooms.reduce((s, [, arr]) => s + arr.length, 0);
    if (rooms.length === 1) {
      // 単一ルーム: 「◯◯さんから N 件」 or 「◯◯さんから新着メッセージ」
      const [roomId, msgs] = rooms[0];
      if (this.shouldRespectRoomCooldown(roomId, now)) {
        // クールダウン中: 既に最近このルームの通知を出した → 集約通知のみ
        this.fireSummary();
      } else {
        this.fireForRoom(roomId, msgs);
      }
    } else {
      // 複数ルーム: サマリ通知
      this.fireSummary();
    }

    this.pendingByRoom.clear();
  }

  private shouldRespectRoomCooldown(roomId: string, now: number): boolean {
    if (typeof window === 'undefined' || !window.localStorage) return false;
    try {
      const raw = window.localStorage.getItem(STORAGE_KEYS.ROOM_LAST_NOTIFY);
      const map = raw ? JSON.parse(raw) as Record<string, number> : {};
      const last = map[roomId] || 0;
      return (now - last) < ROOM_COOLDOWN_MS;
    } catch { return false; }
  }

  private recordRoomNotify(roomId: string, now: number): void {
    if (typeof window === 'undefined' || !window.localStorage) return;
    try {
      const raw = window.localStorage.getItem(STORAGE_KEYS.ROOM_LAST_NOTIFY);
      const map = raw ? JSON.parse(raw) as Record<string, number> : {};
      map[roomId] = now;
      window.localStorage.setItem(STORAGE_KEYS.ROOM_LAST_NOTIFY, JSON.stringify(map));
    } catch {}
  }

  private fireForRoom(roomId: string, msgs: NotificationPayload[]): void {
    const count = msgs.length;
    const last = msgs[msgs.length - 1];
    const title = count > 1
      ? `${last.senderName}さんから${count}件の新着メッセージ`
      : `${last.senderName}さんから新着メッセージ`;
    const body = count > 1 ? `最新: ${last.preview}` : last.preview;
    this.fireNative(title, body, { roomId }, last.senderAvatar);
    this.recordRoomNotify(roomId, Date.now());
  }

  private fireSummary(): void {
    const totalRooms = this.pendingByRoom.size;
    const totalMsgs = Array.from(this.pendingByRoom.values()).reduce((s, a) => s + a.length, 0);
    const title = totalMsgs === 1
      ? '新着メッセージがあります'
      : `${totalRooms}件のチャットで${totalMsgs}件の新着`;
    const body = '未読メッセージを確認してください';
    this.fireNative(title, body, { roomId: null });
  }

  private fireNative(title: string, body: string, data: { roomId: string | null }, icon?: string): void {
    if (this.getPermission() !== 'granted') return;
    try {
      // 注意: renotify / badge は TypeScript 標準型に含まれないブラウザ依存オプションのため
      // any キャストで渡す (Chrome/Edge はサポート、Safari はスキップされるが無害)
      const opts: NotificationOptions & { renotify?: boolean; badge?: string } = {
        body,
        icon: icon || '/schecon-demo/assets/imgs/common/schecon-favicon.png',
        badge: '/schecon-demo/assets/imgs/common/schecon-favicon.png',
        tag: 'schecon-chat', // 同じ tag で上書き (累積させない)
        renotify: false,     // 上書き時は再度音/バイブしない
        silent: false,
      };
      const n = new Notification(title, opts as NotificationOptions);
      n.onclick = () => {
        try {
          window.focus();
          const base = (document.querySelector('base')?.getAttribute('href') || '/').replace(/\/$/, '');
          const target = data.roomId ? `${base}/chat/${data.roomId}` : `${base}/chat`;
          window.location.href = target;
        } finally {
          n.close();
        }
      };
      this.recentNotifyTimes.push(Date.now());
      // Slack ライクな気づく + 耳障りでない SE を再生
      // (ユーザー指示 2026-04-21)
      this.playNotificationChime();
    } catch {
      /* permission revoked or quota */
    }
  }

  /**
   * Slack 風通知音 (2 音チャイム: 高→低の短いグリッサンド)。
   * WebAudio で動的に合成するため音声ファイル不要。
   * 耳障りにならないよう 300ms 以内・マスターボリューム 0.15。
   */
  private playNotificationChime(): void {
    try {
      const Ctx: any = (window as any).AudioContext || (window as any).webkitAudioContext;
      if (!Ctx) return;
      const ctx: AudioContext = this._audioCtx || new Ctx();
      this._audioCtx = ctx;
      // 中断状態なら resume (iOS Safari 対策)
      if (ctx.state === 'suspended') {
        ctx.resume().catch(() => {});
      }
      const now = ctx.currentTime;
      const master = ctx.createGain();
      master.gain.value = 0.15;
      master.connect(ctx.destination);

      // 2 音: 高→低の順 (Slack "knock-brush" 系の印象)
      // 1 音目: C#6 (1109 Hz)
      // 2 音目: G#5 (831 Hz) ※ダウンワード 5度
      const freqs = [1109, 831];
      freqs.forEach((freq, idx) => {
        const start = now + idx * 0.08;
        const dur = 0.18;
        const osc = ctx.createOscillator();
        osc.type = 'sine';
        osc.frequency.value = freq;
        const g = ctx.createGain();
        // ADSR っぽい: 素早く上昇して緩やかに減衰
        g.gain.setValueAtTime(0, start);
        g.gain.linearRampToValueAtTime(1, start + 0.01);
        g.gain.exponentialRampToValueAtTime(0.001, start + dur);
        osc.connect(g).connect(master);
        osc.start(start);
        osc.stop(start + dur + 0.02);
      });
    } catch { /* WebAudio unsupported */ }
  }
  private _audioCtx: AudioContext | null = null;

  // ==================================================================
  // denied 時の再設定ガイダンス (URL 提供)
  // ==================================================================
  /**
   * Chrome / Edge のサイト設定ページへのディープリンクは
   * chrome://settings / edge://settings で直接開けない制約があるため、
   * UI から手順を案内するためのメタ情報を返す。
   */
  getDeniedReenableGuide(): { browser: 'chrome' | 'edge' | 'other'; steps: string[] } {
    const ua = typeof navigator !== 'undefined' ? navigator.userAgent : '';
    const isEdge = /Edg\//.test(ua);
    const isChrome = /Chrome\//.test(ua) && !isEdge;
    if (isChrome) {
      return {
        browser: 'chrome',
        steps: [
          'アドレスバー左の🔒アイコンをクリック',
          '「サイトの設定」を選択',
          '「通知」を「許可」に変更',
          'このページを再読み込み (F5)',
        ],
      };
    }
    if (isEdge) {
      return {
        browser: 'edge',
        steps: [
          'アドレスバー左の🔒アイコンをクリック',
          '「このサイトのアクセス許可」を開く',
          '「通知」を「許可」に変更',
          'このページを再読み込み (F5)',
        ],
      };
    }
    return {
      browser: 'other',
      steps: [
        'ブラウザのアドレスバー左側のアイコンからサイト権限を開く',
        '「通知」を許可に変更',
        'ページを再読み込み',
      ],
    };
  }
}
