import { Injectable, NgZone, OnDestroy } from '@angular/core';
import { BehaviorSubject, Observable, Subject, filter } from 'rxjs';

/**
 * RealtimeGatewayService
 *
 * リアルタイム同期の「接続管理」と「イベントバス」責務を集約する。
 *
 * Phase 1 (現在): BroadcastChannel で同一オリジンの複数タブ間同期
 *   → バックエンドなしで即導入可能。
 *   → 片方のタブで送信 → もう片方のタブの一覧・詳細・小窓に即時反映。
 *
 * Phase 2 (将来): WebSocket 統合
 *   → connect() の中でこの class のみ変更すれば呼び出し元は差し替え不要。
 *   → exponential backoff 再接続、lastSeenAt カーソルでの差分同期を内蔵。
 *
 * Phase 3 (将来): Service Worker + Push API との統合
 *   → SW が受信した push イベントを `postMessage` → gateway 経由で全タブ同期。
 *
 * 設計原則:
 *  - フロー: [送信者] publish() → [チャンネル] → [受信者] on().subscribe()
 *  - 自分送信の重複排除: clientMsgId (UUID) を publish 時に self set に記録、
 *    同じ ID を受け取ったらスキップ (他タブからの再配送を無視)
 *  - イベント型は Discriminated Union で型安全
 *  - SSR / worker / 古いブラウザでも例外で壊れない (defensive)
 */

// ========================================================================
// イベント定義
// ========================================================================
export type RealtimeEvent =
  | { type: 'message.created';   roomId: string; message: RealtimeMessage; clientMsgId?: string }
  | { type: 'thread.created';    room: RealtimeRoomRef; clientMsgId?: string }
  | { type: 'thread.updated';    roomId: string; patch: Partial<RealtimeRoomRef>; clientMsgId?: string }
  | { type: 'unread.updated';    roomId: string; unreadCount: number; clientMsgId?: string }
  | { type: 'message.read';      roomId: string; at: number; clientMsgId?: string }
  | { type: 'connection.open' }
  | { type: 'connection.close';  reason: string }
  | { type: 'connection.error';  error: any };

export interface RealtimeMessage {
  id: string;
  roomId: string;
  text: string;
  time: string;
  isMe: boolean;
  senderName?: string;
}

export interface RealtimeRoomRef {
  id: string;
  name: string;
  initial: string;
  avatarColor: string;
  avatarImage?: string;
  type: 'direct' | 'group' | 'my';
  lastMessage?: string;
  timestamp?: string;
  updatedAt?: number;
  unreadCount?: number;
}

export type ConnectionStatus = 'idle' | 'connecting' | 'open' | 'closed' | 'error';

const CHANNEL_NAME = 'schecon-chat-v1';
const CLIENT_ID_STORAGE = 'schecon.realtime.clientId.v1';
const WS_URL_STORAGE = 'schecon.realtime.wsUrl';        // ユーザが localStorage に設定すると WS 接続を試す
const LAST_SEEN_STORAGE = 'schecon.realtime.lastSeenAt'; // 差分同期カーソル
const WS_RECONNECT_MAX_MS = 30_000;
const WS_RECONNECT_INITIAL_MS = 1_000;

@Injectable({ providedIn: 'root' })
export class RealtimeGatewayService implements OnDestroy {
  private channel: BroadcastChannel | null = null;
  private fallbackStorageHandler: ((e: StorageEvent) => void) | null = null;

  // Phase 2: WebSocket
  private ws: WebSocket | null = null;
  private wsBackoffMs = WS_RECONNECT_INITIAL_MS;
  private wsReconnectTimer: any = null;
  private wsHeartbeatTimer: any = null;
  private lastSeenAt = 0;

  private events$ = new Subject<RealtimeEvent>();
  private status$ = new BehaviorSubject<ConnectionStatus>('idle');

  /** 自分の送信イベント (clientMsgId) を記録し、他タブからの再配送をスキップ */
  private sentClientIds = new Set<string>();
  /** set の無制限肥大を防ぐため、古い ID を定期的に掃除 */
  private clientIdsSweepTimer: any = null;

  /** このタブを識別する ID (ページ読込ごとに生成、タブ横断で共有されない) */
  readonly tabId: string;

  constructor(private ngZone: NgZone) {
    this.tabId = this.createTabId();
    this.lastSeenAt = this.loadLastSeen();
    this.connect();
  }

  ngOnDestroy(): void {
    this.disconnect();
  }

  private loadLastSeen(): number {
    try {
      return Number(localStorage.getItem(LAST_SEEN_STORAGE) || '0') || 0;
    } catch { return 0; }
  }
  private saveLastSeen(ts: number): void {
    try { localStorage.setItem(LAST_SEEN_STORAGE, String(ts)); } catch {}
  }

  // ======================================================================
  // 接続管理
  // ======================================================================
  connect(): void {
    if (this.status$.value === 'open' || this.status$.value === 'connecting') return;
    this.setStatus('connecting');

    // Phase 1: BroadcastChannel (同一オリジンの複数タブ同期)
    if (typeof BroadcastChannel !== 'undefined') {
      try {
        this.channel = new BroadcastChannel(CHANNEL_NAME);
        this.channel.addEventListener('message', this.onChannelMessage);
        this.setStatus('open');
        this.events$.next({ type: 'connection.open' });
      } catch (e) {
        this.fallbackToStorage();
      }
    } else {
      // Safari 15.3 以下など BroadcastChannel 非対応環境
      this.fallbackToStorage();
    }

    // Phase 2: WebSocket (設定されていれば追加で接続)
    // 接続先は localStorage['schecon.realtime.wsUrl'] で指定。
    // 未設定なら WebSocket は使わず Phase 1 のまま (従来の BroadcastChannel 動作)。
    this.tryConnectWebSocket();

    // ID の定期清掃: 5 分おきに古い自送信 ID を GC
    this.clientIdsSweepTimer = setInterval(() => {
      if (this.sentClientIds.size > 300) {
        const arr = Array.from(this.sentClientIds).slice(-200);
        this.sentClientIds = new Set(arr);
      }
    }, 5 * 60 * 1000);
  }

  // ======================================================================
  // Phase 2: WebSocket 接続管理
  // ======================================================================
  private tryConnectWebSocket(): void {
    if (typeof WebSocket === 'undefined' || typeof localStorage === 'undefined') return;
    let url: string | null = null;
    try { url = localStorage.getItem(WS_URL_STORAGE); } catch {}
    if (!url) return;

    // 既存接続があれば切断
    if (this.ws) {
      try { this.ws.close(1000, 'reconnect'); } catch {}
      this.ws = null;
    }

    try {
      this.ws = new WebSocket(url);
    } catch (e) {
      this.events$.next({ type: 'connection.error', error: e });
      this.scheduleWsReconnect();
      return;
    }

    this.ws.onopen = () => {
      this.wsBackoffMs = WS_RECONNECT_INITIAL_MS;
      // 差分同期リクエスト (前回の最終受信以降のイベントを取得)
      try {
        this.ws!.send(JSON.stringify({ type: 'sync.since', since: this.lastSeenAt }));
      } catch {}
      // ハートビート (25 秒おき)
      this.wsHeartbeatTimer = setInterval(() => {
        if (this.ws?.readyState === WebSocket.OPEN) {
          try { this.ws.send(JSON.stringify({ type: 'ping' })); } catch {}
        }
      }, 25000);
    };

    this.ws.onmessage = (e) => {
      let data: any;
      try { data = JSON.parse(e.data); } catch { return; }
      if (!data || !data.type) return;
      // 差分同期カーソル更新
      this.lastSeenAt = Date.now();
      this.saveLastSeen(this.lastSeenAt);
      // サーバからは全クライアントにブロードキャストされるので、自送信でも echo 排除は必要
      this.handleEvent(data as RealtimeEvent);
    };

    this.ws.onclose = (e) => {
      if (this.wsHeartbeatTimer) { clearInterval(this.wsHeartbeatTimer); this.wsHeartbeatTimer = null; }
      this.ws = null;
      this.events$.next({ type: 'connection.close', reason: `ws-closed:${e.code}` });
      // 意図的な close (1000) 以外は再接続を試みる
      if (e.code !== 1000) {
        this.scheduleWsReconnect();
      }
    };

    this.ws.onerror = (err) => {
      this.events$.next({ type: 'connection.error', error: err });
    };
  }

  private scheduleWsReconnect(): void {
    if (this.wsReconnectTimer) return;
    const delay = this.wsBackoffMs;
    this.wsReconnectTimer = setTimeout(() => {
      this.wsReconnectTimer = null;
      this.tryConnectWebSocket();
    }, delay);
    this.wsBackoffMs = Math.min(this.wsBackoffMs * 2, WS_RECONNECT_MAX_MS);
  }

  private fallbackToStorage(): void {
    // storage イベントで代替同期 (localStorage を介した pub/sub)
    if (typeof window === 'undefined' || !window.localStorage) {
      this.setStatus('error');
      this.events$.next({ type: 'connection.error', error: 'no-storage' });
      return;
    }
    this.fallbackStorageHandler = (e: StorageEvent) => {
      if (e.key !== CHANNEL_NAME || !e.newValue) return;
      try {
        const data = JSON.parse(e.newValue) as { ts: number; event: RealtimeEvent; from: string };
        if (data.from === this.tabId) return; // 自タブの書込みはスキップ
        this.handleEvent(data.event);
      } catch {}
    };
    window.addEventListener('storage', this.fallbackStorageHandler);
    this.setStatus('open');
    this.events$.next({ type: 'connection.open' });
  }

  disconnect(): void {
    if (this.channel) {
      try { this.channel.removeEventListener('message', this.onChannelMessage); } catch {}
      try { this.channel.close(); } catch {}
      this.channel = null;
    }
    if (this.fallbackStorageHandler && typeof window !== 'undefined') {
      window.removeEventListener('storage', this.fallbackStorageHandler);
      this.fallbackStorageHandler = null;
    }
    // WebSocket cleanup
    if (this.ws) {
      try { this.ws.close(1000, 'disconnect'); } catch {}
      this.ws = null;
    }
    if (this.wsReconnectTimer) { clearTimeout(this.wsReconnectTimer); this.wsReconnectTimer = null; }
    if (this.wsHeartbeatTimer) { clearInterval(this.wsHeartbeatTimer); this.wsHeartbeatTimer = null; }

    if (this.clientIdsSweepTimer) {
      clearInterval(this.clientIdsSweepTimer);
      this.clientIdsSweepTimer = null;
    }
    this.setStatus('closed');
    this.events$.next({ type: 'connection.close', reason: 'manual' });
  }

  private setStatus(s: ConnectionStatus): void {
    if (this.status$.value === s) return;
    this.ngZone.run(() => this.status$.next(s));
  }

  getStatus(): ConnectionStatus {
    return this.status$.value;
  }

  getStatus$(): Observable<ConnectionStatus> {
    return this.status$.asObservable();
  }

  // ======================================================================
  // 送信 / 購読
  // ======================================================================
  /**
   * イベントを他タブへ発行する。
   * 自分自身の送信は sentClientIds に記録し、echo back をスキップする。
   */
  publish(event: RealtimeEvent): void {
    // clientMsgId の自動付与 (ない場合)
    const eventWithId = this.ensureClientMsgId(event);
    const id = (eventWithId as any).clientMsgId;
    if (id) this.sentClientIds.add(id);

    try {
      // BroadcastChannel (同一ブラウザの他タブ)
      if (this.channel) {
        this.channel.postMessage(eventWithId);
      } else if (typeof window !== 'undefined' && window.localStorage) {
        // storage fallback
        const payload = { ts: Date.now(), event: eventWithId, from: this.tabId };
        window.localStorage.setItem(CHANNEL_NAME, JSON.stringify(payload));
        setTimeout(() => { try { window.localStorage.removeItem(CHANNEL_NAME); } catch {} }, 0);
      }
      // WebSocket (他端末/他ブラウザ)
      if (this.ws?.readyState === WebSocket.OPEN) {
        this.ws.send(JSON.stringify(eventWithId));
      }
    } catch (e) {
      this.events$.next({ type: 'connection.error', error: e });
    }
  }

  /** 全イベントの購読 */
  getEvents$(): Observable<RealtimeEvent> {
    return this.events$.asObservable();
  }

  /** 型付きで特定のイベントだけ購読 */
  on<T extends RealtimeEvent['type']>(type: T): Observable<Extract<RealtimeEvent, { type: T }>> {
    return this.events$.pipe(
      filter((e): e is Extract<RealtimeEvent, { type: T }> => e.type === type),
    );
  }

  // ======================================================================
  // 内部
  // ======================================================================
  private onChannelMessage = (e: MessageEvent): void => {
    this.handleEvent(e.data as RealtimeEvent);
  };

  private handleEvent(event: RealtimeEvent): void {
    // 自分が発行した clientMsgId が付いているものはスキップ (echo back 排除)
    const anyEvent = event as any;
    if (anyEvent.clientMsgId && this.sentClientIds.has(anyEvent.clientMsgId)) {
      return;
    }
    // NgZone 内で通知 (change detection を発火)
    this.ngZone.run(() => this.events$.next(event));
  }

  private ensureClientMsgId<E extends RealtimeEvent>(event: E): E {
    // connection.* は clientMsgId 不要
    if (event.type.startsWith('connection.')) return event;
    const anyEvt = event as any;
    if (!anyEvt.clientMsgId) {
      anyEvt.clientMsgId = this.createClientMsgId();
    }
    return event;
  }

  private createClientMsgId(): string {
    return 'cid-' + Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 10);
  }

  private createTabId(): string {
    // ページ毎にユニーク (storage に記録すると複数タブで衝突するため sessionStorage)
    try {
      if (typeof window !== 'undefined' && window.sessionStorage) {
        const existing = window.sessionStorage.getItem(CLIENT_ID_STORAGE);
        if (existing) return existing;
        const next = 'tab-' + Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 10);
        window.sessionStorage.setItem(CLIENT_ID_STORAGE, next);
        return next;
      }
    } catch {}
    return 'tab-' + Date.now().toString(36);
  }
}
